'use client';

import type { ResourceManagerProps } from "./types.ts";
import { ResourceTable } from "./resource-table";
import { ResourceManagerProvider } from "./resource-manager-context";
import { ResourceFormModalContainer } from "./resource-form-modal-container";
import { ActionButtons } from "./action-buttons";


export function ResourceManager({
  data,
  fields,
  handleCreate,
  handleUpdate,
  resourceName = "Resource",
  title,
  handleSelectionChange,
  handleDelete,
  rowHeight = 40, // Default row height matching the table's default
}: ResourceManagerProps) {
  return (
    <ResourceManagerProvider
      data={data}
      handleCreate={handleCreate}
      handleUpdate={handleUpdate}
      resourceName={resourceName}
      handleSelectionChange={handleSelectionChange}
      handleDelete={handleDelete}
    >
      <div className="flex flex-col gap-4">
        {/* Header with title */}
        <div className="flex">
          <h1 className="text-2xl font-bold">{title}</h1>
        </div>

        {/* Scrollable container with uniform border */}
        <div className="border border-border overflow-hidden">
          <div className="overflow-auto max-w-full">
            <ResourceTable
              fields={fields}
              rowHeight={rowHeight}
            />

            {/* Records summary row - with fixed position styling */}
            <div 
              className="sticky left-0 flex items-center px-4 text-xs text-muted-foreground bg-muted/20 min-w-full border-t border-border"
              style={{ height: `${rowHeight}px` }}
            >
              <span>{data?.length || 0} records</span>
            </div>
          </div>
        </div>

        <ActionButtons />
        <ResourceFormModalContainer fields={fields} />
      </div>
    </ResourceManagerProvider>
  );
}

import * as React from "react";
import {Panel, PanelGroup, PanelResizeHandle} from "react-resizable-panels";
import {Checkbox} from "../ui/checkbox";
import type {FieldConfig} from './types.ts';
import {useResourceManager} from './resource-manager-context';

export interface ResourceTableProps {
    fields: FieldConfig[];
    minColumnWidth?: number;
    rowHeight?: number; // New prop for row height
}

export function ResourceTable({
                                  fields,
                                  minColumnWidth = 10,
                                  rowHeight = 40, // Default row height
                              }: ResourceTableProps) {
    const {
        data,
        selectedIds,
        setSelectedIds,
        handleOpenEdit,
        resourceName,
    } = useResourceManager();

    const [hoveredRow, setHoveredRow] = React.useState<number | null>(null);

    if (!data || data.length === 0) {
        return (
            <div className="text-center py-8 text-muted-foreground">
                No {resourceName.toLowerCase()}s found.
            </div>
        );
    }

    const allSelected = data.length > 0 && selectedIds.length === data.length;
    const handleSelectAll = (checked: boolean) => {
        setSelectedIds(checked ? data.map((row: any) => row.id) : []);
    };

    const handleCheckboxChange = (id: string | number) => {
        setSelectedIds(
            selectedIds.includes(id)
                ? selectedIds.filter((selectedId: string | number) => selectedId !== id)
                : [...selectedIds, id]
        );
    };

    // We don't need the ref anymore as we're using the Checkbox component which handles indeterminate state differently

    return (
        <div className="flex w-full">
            <div className="flex-1">
                <div className="flex min-w-full">
                    {/* Checkbox column as fixed cell */}
                    <div className="flex flex-col" style={{width: 48}}>
                        {/* Header */}
                        <div className="border-b flex items-center justify-center bg-muted/20"
                             style={{height: `${rowHeight}px`, paddingTop: '0.75rem', paddingBottom: '0.75rem'}}>
                            <Checkbox
                                checked={allSelected}
                                onCheckedChange={handleSelectAll}
                                onClick={(e) => e.stopPropagation()}
                                aria-label="Select all"
                            />
                        </div>
                        {/* Column cells */}
                        <div className="flex-1">
                            {data.map((row, rowIdx) => (
                                <div
                                    key={`checkbox-cell-${row.id}`}
                                    className={`border-b last:border-b-0 flex items-center justify-center ${hoveredRow === rowIdx || selectedIds.includes(row.id) ? 'bg-muted' : ''}`}
                                    style={{height: `${rowHeight}px`}}
                                    onMouseEnter={() => setHoveredRow(rowIdx)}
                                    onMouseLeave={() => setHoveredRow(null)}
                                >
                                    {selectedIds.length > 0 || hoveredRow === rowIdx ? (
                                        <Checkbox
                                            checked={selectedIds.includes(row.id)}
                                            onCheckedChange={() => handleCheckboxChange(row.id)}
                                            onClick={(e) => e.stopPropagation()}
                                        />
                                    ) : (
                                        <span className="text-xs text-muted-foreground font-medium">
                      {rowIdx + 1}
                    </span>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                    {/* Main content: resizable columns */}
                    <div className="flex-1">
                        <PanelGroup
                            direction="horizontal"
                            className="min-w-full"
                        >
                            {fields.map((field, index) => (
                                <React.Fragment key={field.key}>
                                    <Panel
                                        defaultSize={100 / fields.length}
                                        minSize={minColumnWidth}
                                    >
                                        <div className="h-full flex flex-col">
                                            {/* Header */}
                                            <div
                                                className="border-b px-4 font-medium text-sm flex items-center bg-muted/20"
                                                style={{
                                                    height: `${rowHeight}px`,
                                                    paddingTop: '0.75rem',
                                                    paddingBottom: '0.75rem'
                                                }}>
                                                {field.label}
                                            </div>
                                            {/* Column cells */}
                                            <div className="flex-1">
                                                {data.map((row, rowIdx) => (
                                                    <div
                                                        key={rowIdx}
                                                        className={`px-4 text-sm border-b last:border-b-0 flex items-center cursor-pointer ${
                                                            hoveredRow === rowIdx || selectedIds.includes(row.id) ? 'bg-muted' : ''
                                                        }`}
                                                        style={{height: `${rowHeight}px`}}
                                                        onClick={() => handleOpenEdit(rowIdx)}
                                                        onMouseEnter={() => setHoveredRow(rowIdx)}
                                                        onMouseLeave={() => setHoveredRow(null)}
                                                    >
                                                        <div className="truncate w-full">
                                                            {(() => {
                                                                const value = field.renderCell ? field.renderCell(row[field.key], row) : row[field.key];
                                                                if (value === null || value === undefined) return '-';
                                                                if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean' || React.isValidElement(value)) {
                                                                    return value;
                                                                }
                                                                return '-';
                                                            })()}
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    </Panel>
                                    {index < fields.length - 1 && (
                                        <PanelResizeHandle
                                            className="w-0.5 bg-transparent group hover:bg-muted cursor-col-resize transition-all duration-200 ease-in-out flex items-center justify-center">
                                            <div
                                                className="w-0.5 h-full bg-border group-hover:bg-muted-foreground group-hover:w-1 transition-all duration-200"/>
                                        </PanelResizeHandle>
                                    )}
                                </React.Fragment>
                            ))}
                        </PanelGroup>
                    </div>
                </div>
            </div>
        </div>
    );
}

import React from 'react';
import { Button } from "@/components/ui/button";
import { PlusCircle, Trash2 } from "lucide-react";
import { useResourceManager } from './resource-manager-context';
import { DeleteConfirmationDialog } from './delete-confirmation-dialog';

export function ActionButtons() {
  const { 
    resourceName, 
    handleOpenCreate, 
    handleDelete,
    selectedIds 
  } = useResourceManager();

  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = React.useState(false);

  const handleLocalDelete = () => {
    if (selectedIds.length > 0) {
      handleDelete(selectedIds);
      setIsDeleteDialogOpen(false);
    }
  };

  return (
    <>
      <DeleteConfirmationDialog
        open={isDeleteDialogOpen}
        onOpenChange={setIsDeleteDialogOpen}
        selectedIds={selectedIds}
        onConfirm={handleLocalDelete}
        resourceName={resourceName}
      />

      <div className="flex gap-2 justify-end">
        <Button
          className="cursor-pointer"
          variant="destructive"
          onClick={() => setIsDeleteDialogOpen(true)}
          disabled={selectedIds.length === 0}
        >
          <Trash2 className="w-4 h-4" />
          Delete Selected ({selectedIds.length})
        </Button>
        <Button className="cursor-pointer" onClick={handleOpenCreate}>
          <PlusCircle className="w-4 h-4" />
          Add {resourceName}
        </Button>
      </div>
    </>
  );
}

import {useContext} from "react";
import {ResourceManagerContext} from "./resource-manager-context";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
} from "../ui/dialog";
import {Button} from "../ui/button";
import {AlertTriangle} from "lucide-react";

interface DeleteConfirmationDialogProps {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    selectedIds: Array<string | number>;
    onConfirm: () => void;
    resourceName: string;
}

export function DeleteConfirmationDialog({
                                             open,
                                             onOpenChange,
                                             selectedIds,
                                             onConfirm,
                                             resourceName,
                                         }: DeleteConfirmationDialogProps) {
    const ctx = useContext(ResourceManagerContext);
    const items = ctx?.data?.filter(item => selectedIds.includes(item.id)) || [];
    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent>
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2 text-destructive">
                        <AlertTriangle className="size-5 text-destructive"/>
                        Delete {resourceName}s
                    </DialogTitle>
                    <DialogDescription>
                        Are you sure you want to delete the following {resourceName.toLowerCase()}s?
                    </DialogDescription>
                    <div className="mt-4 p-2 bg-muted rounded-md max-h-64 overflow-y-auto">
                        {items.map((item) => (
                            <div key={String(item.id)} className="text-sm py-1 border-b last:border-b-0 flex flex-col gap-1">
                                <span><b>ID:</b> {String(item.id)}</span>
                                {typeof item.name === 'string' && <span><b>Name:</b> {item.name}</span>}
                                {typeof item.email === 'string' && <span><b>Email:</b> {item.email}</span>}
                                {typeof item.role === 'string' && <span><b>Role:</b> {item.role}</span>}
                            </div>
                        ))}
                    </div>

                </DialogHeader>
                <div className="flex justify-end gap-2 mt-6">
                    <Button variant="outline" onClick={() => onOpenChange(false)}>
                        Cancel
                    </Button>
                    <Button
                        variant="destructive"
                        onClick={() => {
                            onConfirm();
                            onOpenChange(false);
                        }}
                    >
                        Delete
                    </Button>
                </div>
            </DialogContent>
        </Dialog>
    );
}

import React from 'react';
import type {Item, ResourceManagerProps, ModalMode} from "./types.ts";

interface ResourceManagerContextType {
    data: Item[];
    selectedIds: Array<string | number>;
    modalOpen: boolean;
    editIdx: number | null;
    mode: ModalMode;
    formValues: Partial<Item>;
    resourceName: string;
    setSelectedIds: (ids: Array<string | number>) => void;
    setModalOpen: (open: boolean) => void;
    handleOpenCreate: () => void;
    handleOpenEdit: (idx: number) => void;
    handleDelete: (ids: Array<string | number>) => void;
    handleCloseModal: () => void;
    handleSubmitForm: (values: Partial<Item>) => void;
}

export const ResourceManagerContext = React.createContext<ResourceManagerContextType | undefined>(undefined);

export function ResourceManagerProvider({
                                            children,
                                            data,
                                            handleCreate,
                                            handleUpdate,
                                            handleDelete: onDelete,
                                            resourceName = "Resource",
                                            handleSelectionChange,
                                        }: Pick<ResourceManagerProps, 'data' | 'handleCreate' | 'handleUpdate' | 'resourceName' | 'handleSelectionChange'> & {
    children: React.ReactNode;
    handleDelete?: (ids: Array<string | number>) => void;
}) {
    const [selectedIds, setSelectedIds] = React.useState<Array<string | number>>([]);
    const [modalOpen, setModalOpen] = React.useState(false);
    const [editIdx, setEditIdx] = React.useState<number | null>(null);
    const [mode, setMode] = React.useState<ModalMode>("add");
    const [formValues, setFormValues] = React.useState<Partial<Item>>({});

    const handleOpenCreate = React.useCallback(() => {
        setEditIdx(null);
        setFormValues({});
        setMode("add");
        setModalOpen(true);
    }, []);

    const handleOpenEdit = React.useCallback((idx: number) => {
        setEditIdx(idx);
        setFormValues(data[idx] ?? {});
        setMode("edit");
        setModalOpen(true);
    }, [data]);

    const handleCloseModal = React.useCallback(() => {
        setModalOpen(false);
        setEditIdx(null);
        setFormValues({});
    }, []);

    const handleDelete = React.useCallback((ids: Array<string | number>) => {
        if (onDelete) {
            onDelete(ids);
            setSelectedIds([]);
        }
    }, [onDelete]);

    const handleSubmitForm = React.useCallback((values: Partial<Item>) => {
        if (mode === "add") {
            handleCreate(values);
        } else if (mode === "edit" && editIdx !== null) {
            const id = data[editIdx]?.id;
            if (id) {
                handleUpdate(String(id), values);
            }
        }
        handleCloseModal();
    }, [mode, handleCreate, handleUpdate, editIdx, data, handleCloseModal]);

    React.useEffect(() => {
        handleSelectionChange?.(selectedIds);
    }, [selectedIds, handleSelectionChange]);

    const value = React.useMemo(() => ({
        data,
        selectedIds,
        modalOpen,
        editIdx,
        mode,
        formValues,
        resourceName,
        setSelectedIds,
        setModalOpen,
        handleOpenCreate,
        handleOpenEdit,
        handleDelete,
        handleCloseModal,
        handleSubmitForm,
    }), [
        data,
        selectedIds,
        modalOpen,
        editIdx,
        mode,
        formValues,
        resourceName,
        handleOpenCreate,
        handleOpenEdit,
        handleDelete,
        handleCloseModal,
        handleSubmitForm,
    ]);

    return (
        <ResourceManagerContext.Provider value={value}>
            {children}
        </ResourceManagerContext.Provider>
    );
}

export function useResourceManager() {
    const context = React.useContext(ResourceManagerContext);
    if (context === undefined) {
        throw new Error('useResourceManager must be used within a ResourceManagerProvider');
    }
    return context;
}

import { ResourceFormModal } from "./resource-form-generator/resource-form-modal";
import { useResourceManager } from './resource-manager-context';
import type { FieldConfig } from './types.ts';

interface ResourceFormModalContainerProps {
  fields: FieldConfig[];
}

export function ResourceFormModalContainer({ fields }: ResourceFormModalContainerProps) {
  const {
    modalOpen,
    setModalOpen,
    formValues,
    handleSubmitForm,
    handleCloseModal,
    mode,
    resourceName,
  } = useResourceManager();

  if (!modalOpen) return null;

  return (
    <ResourceFormModal
      isOpen={modalOpen}
      onOpenChange={setModalOpen}
      initialValues={formValues}
      onSubmit={handleSubmitForm}
      onCancel={handleCloseModal}
      mode={mode}
      resourceName={resourceName}
      fields={fields}
    />
  );
}

import { Dialog, DialogTitle } from "@radix-ui/react-dialog";
import { DialogContent, DialogHeader } from "@/components/ui/dialog";
import type { ResourceFormModalProps } from "./form-types.ts";
import { ResourceFormGenerator } from "./resource-form-generator.tsx";


/**
 * Modal component for resource forms
 * 
 * Handles the dialog UI wrapper around the form component
 */
export function ResourceFormModal({
  isOpen,
  onOpenChange,
  initialValues,
  onSubmit,
  onCancel,
  mode,
  resourceName,
  fields
}: ResourceFormModalProps) {
  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="bg-card rounded shadow-lg p-6 min-w-[350px] max-w-[95vw]">
        <DialogHeader>
          <DialogTitle>
            {mode === "add" ? "Create New" : "Edit"} {resourceName}
          </DialogTitle>
        </DialogHeader>
        <ResourceFormGenerator
          fields={fields}
          initialValues={initialValues}
          onSubmit={onSubmit}
          onCancel={onCancel}
          mode={mode}
        />
      </DialogContent>
    </Dialog>
  );
}

import { useForm, Controller } from 'react-hook-form';
import type { FieldValues } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Button } from '@/components/ui/button';
import { InputText } from './inputs/input-text.tsx';
import { InputTextarea } from './inputs/input-textarea.tsx';
import { InputSelect } from './inputs/input-select.tsx';
import { InputFile } from './inputs/input-file.tsx';
import type { ResourceFormGeneratorProps } from './form-types.ts';
import type { Item } from '../types.ts';


/**
 * Dynamically generates a form based on field definitions using React Hook Form
 */
export function ResourceFormGenerator({
  fields, 
  initialValues, 
  onSubmit, 
  onCancel,
  mode 
}: ResourceFormGeneratorProps) {
  // Dynamically build a zod schema based on field definitions
  const generateSchema = () => {
    const schemaMap: Record<string, any> = {};

    fields.forEach((field) => {
      const fieldKey = String(field.key);
      // If zodSchema is provided, use it. Otherwise, make the field optional.
      schemaMap[fieldKey] = field.zodSchema ? field.zodSchema : z.any().optional();
    });
    return z.object(schemaMap);
  };

  const schema = generateSchema();

  // Use FieldValues for react-hook-form generics for compatibility
  const {
    control,
    handleSubmit,
    formState: { errors },
  } = useForm<FieldValues>({
    resolver: zodResolver(schema),
    defaultValues: initialValues as any,
  });

  // Form submission handler
  const onFormSubmit = (data: FieldValues) => {
    onSubmit(data as Partial<Item>);
  };

  // Input component mapping
  const inputComponents: Record<string, any> = {
    text: InputText,
    textarea: InputTextarea,
    select: InputSelect,
    file: InputFile,
  };

  return (
    <form onSubmit={handleSubmit(onFormSubmit)} className="space-y-4">
      {fields.map((field) => {
        const fieldKey = String(field.key);
        const InputComponent = inputComponents[field.inputType] || InputText;
        return (
          <div key={fieldKey} className="space-y-2">
            <label 
              htmlFor={fieldKey} 
              className="block text-sm font-medium text-gray-700"
            >
              {field.label} {(field.zodSchema) && <span className="text-red-500">*</span>}
            </label>
            <Controller
              name={fieldKey}
              control={control}
              render={({ field: formField }) => (
                <InputComponent
                  id={fieldKey}
                  field={formField}
                  {...(field.inputType === 'select' ? { label: field.label, options: field.options } : {})}
                  {...(field.inputType === 'file' ? { onFileUpload: field.onFileUpload } : {})}
                />
              )}
            />
            {errors[fieldKey] && (
              <p className="text-red-500 text-sm">
                {errors[fieldKey]?.message?.toString()}
              </p>
            )}
          </div>
        );
      })}

      <div className="flex justify-end space-x-2 pt-4">
        <Button type="button" variant="default" onClick={onCancel}>
          Cancel
        </Button>
        <Button type="submit" variant="default">
          {mode === 'add' ? 'Create' : 'Update'}
        </Button>
      </div>
    </form>
  );
}

import { Input } from '@/components/ui/input';
import type { ControllerRenderProps } from 'react-hook-form';

interface InputTextProps {
  id: string;
  field: ControllerRenderProps<any, string>;
}

export function InputText({ id, field }: InputTextProps) {
  const value = field.value ?? '';
  return (
    <Input
      id={id}
      type="text"
      className="w-full"
      {...field}
      value={value}
    />
  );
}

import { Textarea } from '@/components/ui/textarea';
import type { ControllerRenderProps } from 'react-hook-form';

interface InputTextareaProps {
  id: string;
  field: ControllerRenderProps<any, string>;
}

export function InputTextarea({ id, field }: InputTextareaProps) {
  const value = field.value ?? '';
  return (
    <Textarea
      id={id}
      className="w-full p-2 border border-gray-300 rounded-md"
      rows={4}
      {...field}
      value={value}
    />
  );
}

import { Select, SelectTrigger, SelectValue, SelectContent, SelectGroup, SelectItem, SelectLabel } from '@/components/ui/select';
import type { FieldValues, FieldPath, ControllerRenderProps } from 'react-hook-form';

interface Option {
  label: string;
  value: string;
}

interface InputSelectProps<TFieldValues extends FieldValues = FieldValues, TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>> {
  label: string;
  field: ControllerRenderProps<TFieldValues, TName>;
  options?: Option[];
}

export function InputSelect<TFieldValues extends FieldValues = FieldValues, TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>>({ label, field, options }: InputSelectProps<TFieldValues, TName>) {
  const value = field.value ?? '';
  return (
    <Select value={value} onValueChange={field.onChange}>
      <SelectTrigger className="w-full">
        <SelectValue placeholder={`Select ${label}`} />
      </SelectTrigger>
      <SelectContent>
        <SelectGroup>
          {options && options.length > 0 && <SelectLabel>{label}</SelectLabel>}
          {(options ?? []).map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectGroup>
      </SelectContent>
    </Select>
  );
}

import { useRef, useState } from 'react';
import { Button } from '@/components/ui/button';
import { FileUp } from 'lucide-react';
import type { ControllerRenderProps } from 'react-hook-form';
import type { Item } from '../../types.ts';

interface InputFileProps {
  id: string;
  field: ControllerRenderProps<Item, string>;
  onFileUpload?: (file: File) => Promise<string>;
}

export function InputFile({ id, field, onFileUpload }: InputFileProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [fileName, setFileName] = useState<string>("");
  const [uploading, setUploading] = useState(false);
  const [uploaded, setUploaded] = useState(false);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    if (file) {
      setFileName(file.name);
      setUploading(true);
      if (onFileUpload) {
        const url = await onFileUpload(file);
        field.onChange(url);
        setUploaded(true);
      } else {
        field.onChange(file);
      }
      setUploading(false);
    } else {
      setFileName("");
      setUploaded(false);
      field.onChange("");
    }
  };

  return (
    <div className="flex flex-col gap-2">
      <input
        ref={inputRef}
        id={id}
        type="file"
        className="hidden"
        onChange={handleFileChange}
      />
      <Button type="button" variant="outline" onClick={() => inputRef.current?.click()} disabled={uploading}>
        <FileUp className="mr-2" />
        {uploading
          ? 'Uploading...'
          : fileName
            ? (uploaded ? 'Replace file' : 'Upload file')
            : 'Upload file'}
      </Button>
      {fileName && (
        <div className="text-xs text-muted-foreground flex items-center gap-2">
          <span>{fileName}</span>
          {uploading && <span className="animate-pulse text-blue-600">Uploading...</span>}
          {uploaded && !uploading && <span className="text-green-600">✓ Uploaded</span>}
        </div>
      )}
    </div>
  );
}

// Export all components and types
export * from './types.ts';
export { ResourceManager } from './resource-manager.tsx';
export { ResourceTable } from './resource-table.tsx';
export { ResourceFormModal } from './resource-form-generator/resource-form-modal.tsx';

import type {ReactNode} from 'react';
import type { ZodType } from 'zod';

export type Item<T extends Record<string, unknown> = Record<string, unknown>> = {
  id: string;
} & T;

export type InputType = 'text' | 'select' | 'textarea' | 'file';


export interface FieldConfig {
  key: string;
  label: string;
  inputType: InputType;
  renderCell?: <T extends Record<string, unknown> = Record<string, unknown>>(value: unknown, row?: Item<T>) => ReactNode;
  // Optional array of options for select input fields
  options?: Array<{ label: string; value: string }>;
  // Optional file upload handler for file input fields
  onFileUpload?: (file: File) => Promise<string | null>; 
  // Optional Zod schema for field validation
  zodSchema?: ZodType<unknown>;
}

export type ModalMode = "add" | "edit";

export interface ResourceManagerProps<T extends Record<string, unknown> = Record<string, unknown>> {
  title: string;
  resourceName: string;
  data: Array<Item<T>>;
  fields: Array<FieldConfig>;
  handleCreate: (values: Partial<Item<T>>) => void;
  handleUpdate: (id: string, values: Partial<Item<T>>) => void;
  handleDelete: (ids: Array<string | number>) => void;
